<?php
$edit=null;if(isset($_GET['edit'])&&is_staff()){$q=db()->prepare('SELECT * FROM appointments WHERE id=?');$q->execute([(int)$_GET['edit']]);$edit=$q->fetch();}
$date=$_GET['date']??date('Y-m-d');if(!valid_date((string)$date))$date=date('Y-m-d');$status=$_GET['status']??'all';$search=trim((string)($_GET['q']??''));$view=$_GET['view']??'day';if(!in_array($view,['day','week','month'],true))$view='day';$anchor=new DateTimeImmutable($date);$rangeStart=$view==='week'?$anchor->modify('monday this week')->format('Y-m-d'):($view==='month'?$anchor->modify('first day of this month')->format('Y-m-d'):$date);$rangeEnd=$view==='week'?$anchor->modify('sunday this week')->format('Y-m-d'):($view==='month'?$anchor->modify('last day of this month')->format('Y-m-d'):$date);
$sql="SELECT a.*,c.full_name customer_name,s.name service_name,s.duration_minutes,th.full_name therapist_name FROM appointments a JOIN customers c ON c.id=a.customer_id JOIN services s ON s.id=a.service_id JOIN therapists th ON th.id=a.therapist_id WHERE a.appointment_date BETWEEN ? AND ?";$params=[$rangeStart,$rangeEnd];if($status!=='all'){$sql.=' AND a.status=?';$params[]=$status;}if($search!==''){$sql.=' AND (c.full_name LIKE ? OR th.full_name LIKE ? OR a.appointment_code LIKE ?)';array_push($params,"%$search%","%$search%","%$search%");}if(is_therapist()){$sql.=' AND a.therapist_id=?';$params[]=(int)(current_user()['therapist_id']??0);}$sql.=' ORDER BY a.appointment_date,a.start_time';$q=db()->prepare($sql);$q->execute($params);$appointments=$q->fetchAll();
$customers=$services=$therapists=[];if(is_staff()){$customers=db()->query("SELECT id,customer_code,full_name FROM customers WHERE status='active' ORDER BY full_name")->fetchAll();$services=db()->query("SELECT id,name,duration_minutes,price FROM services WHERE status='active' ORDER BY name")->fetchAll();$therapists=db()->query("SELECT id,full_name FROM therapists WHERE status='active' AND availability_status='available' ORDER BY full_name")->fetchAll();if($edit && !in_array((int)$edit['therapist_id'],array_column($therapists,'id'),true)){$q=db()->prepare("SELECT id,full_name FROM therapists WHERE id=? AND status='active'");$q->execute([(int)$edit['therapist_id']]);if($row=$q->fetch())$therapists[]=$row;}}
?>
<div class="page-heading"><div><div class="eyebrow">Schedule management</div><h1>Appointments</h1><p>Book sessions, assign therapists, and manage daily appointment status.</p></div><?php if(is_staff()):?><button class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#appointmentModal"><i class="bi bi-calendar-plus me-1"></i>New appointment</button><?php endif;?></div>
<div class="card"><div class="card-body border-bottom"><div class="d-flex gap-2 mb-3"><?php foreach(['day'=>'Day','week'=>'Week','month'=>'Month'] as $v=>$label):?><a class="btn btn-sm <?=$view===$v?'btn-primary':'btn-outline-secondary'?>" href="<?=h(app_page_url('appointments',['date'=>$date,'view'=>$v,'status'=>$status]))?>"><?=$label?></a><?php endforeach;?></div><form class="row g-2 align-items-end"><input type="hidden" name="page" value="appointments"><input type="hidden" name="view" value="<?=h($view)?>"><div class="col-auto"><label class="form-label">Schedule date</label><input class="form-control" type="date" name="date" value="<?=h($date)?>"></div><div class="col-auto"><label class="form-label">Status</label><select class="form-select" name="status"><option value="all">All statuses</option><?php foreach(['pending','confirmed','checked_in','in_session','completed','cancelled','no_show'] as $s):?><option value="<?=$s?>" <?=selected($status,$s)?>><?=ucwords(str_replace('_',' ',$s))?></option><?php endforeach;?></select></div><div class="col-auto"><label class="form-label">Search</label><input class="form-control" name="q" value="<?=h($search)?>" placeholder="Customer / therapist / ID"></div><div class="col-auto"><button class="btn btn-outline-secondary">Apply filters</button></div><div class="col-auto"><a href="<?=h(app_page_url('appointments',['date'=>date('Y-m-d')]))?>" class="btn btn-light">Today</a></div></form></div><div class="table-responsive"><table class="table"><thead><tr><?php if($view!=='day'):?><th>Date</th><?php endif;?><th>Time</th><th>Customer</th><th>Service</th><th>Therapist</th><th>Payment</th><th>Status</th><th class="text-end">Actions</th></tr></thead><tbody><?php if(!$appointments)echo table_empty($view==='day'?7:8,'No appointments found for this schedule range.');foreach($appointments as $a):?><tr><?php if($view!=='day'):?><td><?=date_label($a['appointment_date'])?></td><?php endif;?><td class="fw-bold"><?=date('g:i A',strtotime($a['start_time']))?><div class="small-muted">to <?=date('g:i A',strtotime($a['end_time']))?></div></td><td><?=h($a['customer_name'])?><div class="small-muted"><?=h($a['appointment_code'])?></div></td><td><?=h($a['service_name'])?><div class="small-muted"><?=h($a['duration_minutes'])?> minutes</div></td><td><?=h($a['therapist_name'])?></td><td><?=status_badge($a['payment_status'])?></td><td><?=status_badge($a['status'])?></td><td class="text-end"><div class="d-flex gap-1 justify-content-end"><?php if(is_staff()):?><a class="btn btn-sm btn-light" href="<?=h(app_page_url('appointments',['edit'=>$a['id'],'date'=>$date]))?>" title="Edit"><i class="bi bi-pencil"></i></a><?php endif;?><?php if($a['status']==='completed' && $a['id']): $sessionLookup=db()->prepare('SELECT id FROM sessions WHERE appointment_id=? LIMIT 1'); $sessionLookup->execute([$a['id']]); $sid=$sessionLookup->fetchColumn(); if($sid):?><a class="btn btn-sm btn-light" href="<?=h(app_page_url('session',['id'=>$sid]))?>" title="Session notes"><i class="bi bi-journal-text"></i></a><?php endif; endif;?><?php if(is_staff() && in_array($a['status'],['pending','confirmed','checked_in','in_session'],true)):?><?=post_form_start('appointment_status',app_page_url('appointments',['date'=>$date,'view'=>$view]))?><input type="hidden" name="id" value="<?=$a['id']?>"><input type="hidden" name="status" value="<?=($a['status']==='pending'?'confirmed':($a['status']==='confirmed'?'checked_in':($a['status']==='checked_in'?'in_session':'completed')))?>"><button class="btn btn-sm btn-light" title="Advance status"><i class="bi bi-arrow-right-circle"></i></button></form><?php elseif(is_therapist() && in_array($a['status'],['checked_in','in_session'],true)):?><?=post_form_start('appointment_status',app_page_url('appointments',['date'=>$date,'view'=>$view]))?><input type="hidden" name="id" value="<?=$a['id']?>"><input type="hidden" name="status" value="<?=$a['status']==='checked_in'?'in_session':'completed'?>"><button class="btn btn-sm btn-light" title="<?=$a['status']==='checked_in'?'Start session':'Complete session'?>"><i class="bi bi-<?=$a['status']==='checked_in'?'play-circle':'check-circle'?>"></i></button></form><?php endif;?><?php if(is_staff() && $a['payment_status']!=='paid' && in_array($a['status'],['checked_in','in_session','completed'],true)):?><a class="btn btn-sm btn-light" href="<?=h(app_page_url('pos',['appointment_id'=>$a['id']]))?>" title="Checkout"><i class="bi bi-cash"></i></a><?php endif;?><?php if(is_staff() && in_array($a['status'],['pending','confirmed','checked_in'],true)):?><?=post_form_start('appointment_status',app_page_url('appointments',['date'=>$date,'view'=>$view]))?><input type="hidden" name="id" value="<?=$a['id']?>"><input type="hidden" name="status" value="no_show"><button class="btn btn-sm btn-light" title="Mark no-show" data-confirm="Mark this appointment as no-show?"><i class="bi bi-person-x"></i></button></form><?=post_form_start('appointment_status',app_page_url('appointments',['date'=>$date,'view'=>$view]))?><input type="hidden" name="id" value="<?=$a['id']?>"><input type="hidden" name="status" value="cancelled"><button class="btn btn-sm btn-light text-danger" title="Cancel appointment" data-confirm="Cancel this appointment?"><i class="bi bi-x-circle"></i></button></form><?php endif;?></div></td></tr><?php endforeach;?></tbody></table></div><div class="card-body d-flex justify-content-between"><span class="small-muted"><?=count($appointments)?> appointment(s) · end times calculated from service duration</span><?php if(is_staff()):?><a href="<?=h(app_page_url('walkins'))?>" class="small text-decoration-none">Open walk-in queue <i class="bi bi-arrow-right"></i></a><?php endif;?></div></div>
<?php if(is_staff()):?><div class="modal fade" id="appointmentModal" tabindex="-1"><div class="modal-dialog modal-lg"><div class="modal-content"><?=post_form_start('save_appointment',app_page_url('appointments',['date'=>$date,'view'=>$view]))?><div class="modal-header"><h5 class="modal-title"><?=$edit?'Edit appointment':'Create appointment'?></h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><?php if($edit):?><input type="hidden" name="id" value="<?=$edit['id']?>"><?php endif;?><div class="row g-3"><div class="col-md-6"><label class="form-label">Customer *</label><select class="form-select" name="customer_id" required><option value="">Select customer</option><?php foreach($customers as $c):?><option value="<?=$c['id']?>" <?=selected($edit['customer_id']??'', $c['id'])?>><?=h($c['full_name'])?> · <?=h($c['customer_code'])?></option><?php endforeach;?></select><div class="form-text"><a href="<?=h(app_page_url('customers',['new'=>1,'return'=>'appointments']))?>">Register a new customer</a> in the customer module.</div></div><div class="col-md-6"><label class="form-label">Service *</label><select class="form-select" name="service_id" required><?php foreach($services as $s):?><option value="<?=$s['id']?>" <?=selected($edit['service_id']??'', $s['id'])?>><?=h($s['name'])?> · <?=$s['duration_minutes']?> min · <?=money($s['price'])?></option><?php endforeach;?></select></div><div class="col-md-6"><label class="form-label">Therapist *</label><select class="form-select" name="therapist_id" required><option value="">Select therapist</option><?php foreach($therapists as $t):?><option value="<?=$t['id']?>" <?=selected($edit['therapist_id']??'', $t['id'])?>><?=h($t['full_name'])?></option><?php endforeach;?></select></div><div class="col-md-3"><label class="form-label">Date *</label><input class="form-control" type="date" name="appointment_date" required value="<?=h($edit['appointment_date']??$date)?>"></div><div class="col-md-3"><label class="form-label">Start time *</label><input class="form-control" type="time" name="start_time" required value="<?=h(isset($edit['start_time'])?substr($edit['start_time'],0,5):'09:00')?>"></div><div class="col-12"><label class="form-label">Notes</label><textarea class="form-control" name="notes" rows="2"><?=h($edit['notes']??'')?></textarea></div></div><div class="alert alert-light border small mt-3 mb-0"><i class="bi bi-info-circle me-1"></i>End time is calculated automatically. The system checks for overlapping bookings for the selected therapist before saving.</div></div><div class="modal-footer"><a href="<?=h(app_page_url('appointments',['date'=>$date,'view'=>$view]))?>" class="btn btn-light">Cancel</a><button class="btn btn-primary">Save appointment</button></form></div></div></div></div><?php if($edit || isset($_GET['new'])):?><script>document.addEventListener('DOMContentLoaded',()=>new bootstrap.Modal(document.getElementById('appointmentModal')).show());</script><?php endif;?><?php endif;?>
